package com.gymmind.workout.domain.model;
import com.gymmind.shared.persistence.TenantScopedEntity; import jakarta.persistence.*; import java.time.LocalDate;
@Entity @Table(name="workout_record") public class WorkoutRecord extends TenantScopedEntity { @Column(name="member_id",nullable=false) private Long memberId; @Column(name="plan_id") private Long planId; @Column(name="workout_date",nullable=false) private LocalDate workoutDate; @Column(nullable=false) private int duration; @Column(nullable=false) private int calories; @Column(nullable=false,length=2000) private String notes; @Enumerated(EnumType.STRING) @Column(nullable=false,length=16) private WorkoutRecordStatus status=WorkoutRecordStatus.COMPLETED; protected WorkoutRecord(){} private WorkoutRecord(Long t,Long m,Long p,LocalDate d,int dur,int cal,String n){super(t);if(m==null||m<=0||d==null||dur<0||cal<0||n==null||n.isBlank())throw new IllegalArgumentException("Invalid workout record");memberId=m;planId=p;workoutDate=d;duration=dur;calories=cal;notes=n.trim();} public static WorkoutRecord create(Long t,Long m,Long p,LocalDate d,int dur,int cal,String n){return new WorkoutRecord(t,m,p,d,dur,cal,n);} public Long getMemberId(){return memberId;} public Long getPlanId(){return planId;} public LocalDate getWorkoutDate(){return workoutDate;} public int getDuration(){return duration;} public int getCalories(){return calories;} public String getNotes(){return notes;} public WorkoutRecordStatus getStatus(){return status;} }
